9	// recycleUpstreamStorage empties the upstream registry by replacing its claim:
10	// the upstream is cut, the claim bench-upstream-data (and nothing else) is
11	// deleted once its label is checked, recreated from its manifest alone, and the
12	// upstream is brought back to one ready replica. The delete is sent once and never
13	// retried; the wait for the claim to be gone lasts until Params.DeleteTimeout.
14	// Like CutUpstream, it runs no preflight (the caller runs OpReset), refuses a
15	// custom upstream before any call, returns a cancelled context as is and accepts
16	// a nil out. A claim that is already gone is not deleted again, so a run that
17	// stopped between the delete and the apply starts again where it stopped.
18	func recycleUpstreamStorage(ctx context.Context, r Runner, clk Clock, p Params, out io.Writer) error {
19		if out == nil {
20			out = io.Discard
21		}
22		if err := CutUpstream(ctx, r, clk, p, out); err != nil {
23			return err
24		}
25		d := &deployer{pf: preflight{r: r, p: p}, w: upstreamWorkload(), tag: "upstream", clk: clk, out: out}
26		if err := d.deleteUpstreamClaim(ctx); err != nil {
27			return err
28		}
29		claim, err := renderUpstreamClaim(p)
30		if err != nil {
31			return err
32		}
33		d.say("creating the claim %s again", upstreamClaimName)
34		if err := d.apply(ctx, "the claim "+upstreamClaimName, claim); err != nil {
35			return err
36		}
