155		}
156		return &BenchError{
157			Kind:  Unclassified,
158			Cause: "the REST origin is not on the loopback, and the admin credentials are sent in clear text, so this command does not send them there",
159			Check: "run this command on the machine that runs the bench, or leave the REST host at its default (127.0.0.1)",
160		}
161	}
