13	// The tests of the recycling of the upstream storage (DEVDESK-534, NX-02b, step 5,
14	// task DEVDESK-552):
15	//
16	//	recycleUpstreamStorage(ctx, runner, clock, p, out) error
17	//
18	// against the scripted kubectl of upstream_test.go (upstreamKubectl) extended below
19	// by recycleKubectl with the two verbs the recycling adds, delete and apply, and the
20	// state of the claim bench-upstream-data, and the fake clock of clock_test.go. No
21	// real kubectl, no real wait, nothing on a cluster.
22	//
23	// Like CutUpstream and EnsureUpstream, recycleUpstreamStorage runs no preflight: its
24	// caller (Reset, step 6) runs OpReset first. The calls the tests assume (arguments
25	// after "kubectl", without --context; "--request-timeout=<d>" is ignored):
26	//
27	//	get deployment bench-upstream -n <ns> -o json        (CutUpstream, EnsureUpstream)
28	//	get pods -n <ns> -l app.kubernetes.io/name=bench-upstream -o json
29	//	get pvc bench-upstream-data -n <ns> -o json          (the label check, then the wait
30	//	                                                      for NotFound, one read per round)
31	//	get pvc -n <ns> -o json                              (the wait of EnsureUpstream)
32	//	scale deployment/bench-upstream --replicas=0|1 -n <ns>
33	//	delete pvc bench-upstream-data -n <ns> --wait=false
34	//	apply --server-side --field-manager=devdesk-nexus-bench -f - (stdin: the claim alone)
35	//
36	// Choices of the tests, to settle with the code (the plan gives the order and the
37	// verbs, not every argument):
38	//   - The order of the writes is exactly: scale to 0, delete of the claim, apply of
39	//     the claim, scale to 1. Nothing else is ever written: not the Deployment of
40	//     Nexus, not nexus-data, not the namespace, no pod, no rollout, no exec.
41	//   - The claim is read by name (get pvc bench-upstream-data -o json) before the
42	//     delete: absent means no delete (the apply and the scale still run); a claim
43	//     without app.kubernetes.io/managed-by=devdesk-nexus-bench means no delete, no
44	//     apply and no scale to 1 (an error, whether the cut came before the read or
45	//     not). The delete is "--wait=false", sent once and never retried; the wait for
46	//     NotFound reads the claim by name every round and is bounded by
47	//     Params.DeleteTimeout, not by Params.Timeout.
48	//   - The apply carries ONE document, the claim: the 5th document of Render, never
49	//     the whole stream (a full apply with other parameters would roll the pod of
50	//     Nexus, which the story forbids). It happens only once the claim is NotFound.
51	//   - The upstream is brought back with EnsureUpstream: scale to 1, then the wait of
52	//     the pods until Ready, bounded by Params.Timeout.
53	//   - Every failure is a *BenchError classified like the others (a delete or a scale
54	//     refused: Forbidden; an apply: applyFailure; a wait: Deadline) whose text has no
55	//     password and none of the stderr of kubectl; no write is retried. A cancelled
56	//     context is returned as is. A custom upstream URL is refused before any call. A
57	//     nil out is accepted.
58	
59	// recycleKubectl answers delete and apply on top of an upstreamKubectl, and the read
60	// of the claim bench-upstream-data by name from a state of its own. The reads of the
61	// list of claims, of the pods and of the Deployments stay with the rounds of the
62	// embedded fake.
63	type recycleKubectl struct {
64		*upstreamKubectl
65	
66		// afterCut and afterRestore are the rounds played after a scale to 0 and after
67		// a scale to 1: the embedded fake has one script after a scale, and the two
68		// scales of the recycling need two.
69		afterCut, afterRestore []upstreamRound
70	
71		claim claimState
72	
73		// The failures a test scripts; each answers its call and has no effect.
74		claimReply, deleteReply, applyReply *fakeReply
75		// scaleFailsFor, when "0" or "1", fails the scale to that count.
76		scaleFailsFor string
77	
78		ops     []string // "scale 0", "scale 1", "delete", "apply", in order, failed ones included
79		deletes []string // the normalized delete calls
80		applies [][]byte // the stdin of every apply
81	}
