110	func (k *recycleKubectl) Run(ctx context.Context, stdin []byte, args ...string) ([]byte, []byte, error) {
111		norm := normalizeArgs(args)
112		switch verb := verbOf(args); verb {
113		case "delete":
114			return k.deleteClaim(norm)
115		case "apply":
116			return k.applyClaim(stdin, norm)
117		case "scale":
118			k.beforeScale(norm)
119		case "get":
120			if g, ok := k.parseGet(norm); ok && g.kind == "pvc" && g.name == upstreamClaim {
121				return k.readClaim(norm)
122			}
123		}
124		return k.upstreamKubectl.Run(ctx, stdin, args...)
125	}
