127	// beforeScale records the scale and picks the rounds that follow it.
128	func (k *recycleKubectl) beforeScale(norm []string) {
129		replicas := ""
130		for _, a := range norm {
131			if v, ok := strings.CutPrefix(a, "--replicas="); ok {
132				replicas = v
133			}
134		}
135		k.ops = append(k.ops, "scale "+replicas)
136		k.scaleReply = nil
137		if replicas == k.scaleFailsFor {
138			k.scaleReply = &fakeReply{
139				stderr: "Error from server (Forbidden): deployments.apps \"bench-upstream\" is forbidden: cannot patch resource \"deployments/scale\" token=" + fakeSecret,
140				err:    errFakeExit1,
141			}
142		}
143		if replicas == "0" {
144			k.after = k.afterCut
145		} else {
146			k.after = k.afterRestore
147		}
148	}
