150	// journal records a call the fake answers itself in the journals of the embedded fake.
151	func (k *recycleKubectl) journal(norm []string, write bool) {
152		line := strings.Join(norm, " ")
153		k.lines = append(k.lines, line)
154		if write {
155			k.writes = append(k.writes, line)
156		}
157	}
