160		meta := map[string]any{"name": upstreamClaim, "namespace": k.p.Namespace, "labels": k.claim.labels}
161		if k.claim.terminating {
162			meta["deletionTimestamp"] = "2026-11-17T09:00:00Z"
163			meta["finalizers"] = []string{"kubernetes.io/pvc-protection"}
