168	func (k *recycleKubectl) readClaim(norm []string) ([]byte, []byte, error) {
169		k.journal(norm, false)
170		if k.claimReply != nil {
171			return k.claimReply.reply()
172		}
173		if k.claim.exists && k.claim.terminating {
174			if k.claim.stuckReads == 0 {
175				k.claim.exists = false
176			} else if k.claim.stuckReads > 0 {
177				k.claim.stuckReads--
178			}
179		}
180		if !k.claim.exists {
181			return notFoundReply("persistentvolumeclaims \"" + upstreamClaim + "\"")
182		}
183		return k.mustJSON(k.claimObject()), nil, nil
184	}
