186	func (k *recycleKubectl) deleteClaim(norm []string) ([]byte, []byte, error) {
187		k.journal(norm, true)
188		k.ops = append(k.ops, "delete")
189		k.deletes = append(k.deletes, strings.Join(norm, " "))
190		var positional []string
191		waitFalse := false
192		namespace := ""
193		for i := 1; i < len(norm); i++ {
194			switch a := norm[i]; {
195			case a == "-n" || a == "--namespace":
196				i++
197				namespace = at(norm, i)
198			case a == "--wait=false":
199				waitFalse = true
200			case strings.HasPrefix(a, "-"):
201				k.t.Errorf("unscripted argument %q in %q", a, norm)
202			default:
203				positional = append(positional, a)
204			}
205		}
206		if got := strings.Join(positional, "/"); got != "pvc/"+upstreamClaim && got != "persistentvolumeclaim/"+upstreamClaim {
207			k.t.Errorf("delete targets %q, want pvc/%s: nothing else is ever deleted", got, upstreamClaim)
208			return nil, []byte("the fake refuses this delete"), errFakeExit1
209		}
210		if namespace != k.p.Namespace {
211			k.t.Errorf("delete in namespace %q, the run is about %q", namespace, k.p.Namespace)
212		}
213		if !waitFalse {
214			k.t.Errorf("delete without --wait=false: %q (the wait is the bounded one of the code, not kubectl's)", norm)
215		}
216		if k.deleteReply != nil {
217			return k.deleteReply.reply()
218		}
219		if !k.claim.exists {
220			return notFoundReply("persistentvolumeclaims \"" + upstreamClaim + "\"")
221		}
222		k.claim.terminating = true
223		return []byte("persistentvolumeclaim \"" + upstreamClaim + "\" deleted\n"), nil, nil
224	}
