226	func (k *recycleKubectl) applyClaim(stdin []byte, norm []string) ([]byte, []byte, error) {
227		k.journal(norm, true)
228		k.ops = append(k.ops, "apply")
229		k.applies = append(k.applies, bytes.Clone(stdin))
230		joined := strings.Join(norm, " ")
231		for _, want := range []string{"--server-side", "--field-manager=" + fieldManager, "-f -"} {
232			if !strings.Contains(joined, want) {
233				k.t.Errorf("apply %q lacks %q", joined, want)
234			}
235		}
236		if k.applyReply != nil {
237			return k.applyReply.reply()
238		}
239		if k.claim.exists {
240			k.t.Errorf("apply while the claim still exists (terminating: %v): it must be NotFound first", k.claim.terminating)
241			return nil, []byte("the fake refuses an apply over a live claim"), errFakeExit1
242		}
243		k.claim = claimState{exists: true, labels: benchLabels(), phase: "Pending"}
244		return []byte("persistentvolumeclaim/" + upstreamClaim + " serverside-applied\n"), nil, nil
245	}
