308	func (e *recycleEnv) requireTouchesOnlyTheUpstream() {
309		e.t.Helper()
310		for _, w := range e.kube.writes {
311			verb := strings.Fields(w)[0]
312			if !slices.Contains([]string{"scale", "delete", "apply"}, verb) {
313				e.t.Errorf("write %q: the verbs of the recycling are scale, delete and apply", w)
314			}
315			for _, banned := range []string{"nexus-data", "deployment/nexus ", "namespace", "rollout", "pod", "exec"} {
316				if strings.Contains(w, banned) {
317					e.t.Errorf("write %q contains %q: the recycling touches the upstream and its claim only", w, banned)
318				}
319			}
320		}
321		for _, l := range e.kube.lines {
322			if strings.Contains(l, "nexus-data") {
323				e.t.Errorf("call %q names the claim of Nexus", l)
324			}
325		}
326	}
