328	// requireTheClaimAlone checks the stdin of the apply is the one document of the
329	// claim of the upstream, the one the full stream of Render holds.
330	func (e *recycleEnv) requireTheClaimAlone(stdin []byte) {
331		e.t.Helper()
332		doc := string(stdin)
333		full, err := Render(e.p)
334		if err != nil {
335			e.t.Fatalf("Render: %v", err)
336		}
337		if !strings.Contains(string(full), doc) {
338			e.t.Errorf("the applied document is not a document of Render:\n%s", doc)
339		}
340		for _, line := range strings.Split(doc, "\n") {
341			if strings.TrimSpace(line) == "---" {
342				e.t.Errorf("the applied stream has several documents: %q", doc)
343			}
344		}
345		for _, want := range []string{"kind: PersistentVolumeClaim", "name: " + upstreamClaim} {
346			if !strings.Contains(doc, want) {
347				e.t.Errorf("the applied document lacks %q:\n%s", want, doc)
348			}
349		}
350		for _, banned := range []string{"kind: Deployment", "kind: Service", "kind: Namespace", "nexus-data"} {
351			if strings.Contains(doc, banned) {
352				e.t.Errorf("the applied stream contains %q: only the claim of the upstream is applied", banned)
353			}
354		}
355	}
