359	func TestRecycleUpstreamStorageReplacesTheClaim(t *testing.T) {
360		e := newRecycleEnv(t, recycleParams())
361		if err := e.recycle(context.Background()); err != nil {
362			t.Fatalf("recycleUpstreamStorage: %v", err)
363		}
364		e.requireOps("scale 0", "delete", "apply", "scale 1")
365		e.requireTouchesOnlyTheUpstream()
366		e.kube.requireNoPreflight()
367		e.requireNoSecret(nil)
368	
369		// The upstream is cut before the claim is deleted, and read before it is deleted.
370		scale0 := indexOfLine(e.kube.lines, "scale ")
371		label := indexOfLine(e.kube.lines, "get pvc bench-upstream-data")
372		del := indexOfLine(e.kube.lines, "delete ")
373		if scale0 < 0 || del < scale0 {
374			t.Errorf("the delete does not follow the scale to 0: %q", e.kube.lines)
375		}
376		if label < 0 || del < label {
377			t.Errorf("the claim is not read before it is deleted: %q", e.kube.lines)
378		}
379		// The pods are listed until none is left before the claim goes.
380		if pods := indexOfLine(e.kube.lines[scale0+1:], "get pods"); pods < 0 || scale0+1+pods > del {
381			t.Errorf("no pod read between the scale to 0 and the delete: %q", e.kube.lines)
382		}
383	
384		if len(e.k.deletes) != 1 {
385			t.Errorf("%d deletes, want one: %q", len(e.k.deletes), e.k.deletes)
386		}
387		if len(e.k.applies) != 1 {
388			t.Fatalf("%d applies, want one", len(e.k.applies))
389		}
390		e.requireTheClaimAlone(e.k.applies[0])
391	
392		// The new claim is in place and the upstream is ready.
393		if !e.k.claim.exists || e.k.claim.terminating {
394			t.Errorf("the claim after the recycling: %+v", e.k.claim)
395		}
396		if !strings.Contains(e.out.String(), "upstream: ") {
397			t.Errorf("progress lines %q do not carry the upstream: prefix", e.out.String())
398		}
399	}
