401	func TestRecycleUpstreamStorageWaitsForTheClaimToBeGoneBeforeTheApply(t *testing.T) {
402		e := newRecycleEnv(t, recycleParams())
403		e.k.claim.stuckReads = 3
404		if err := e.recycle(context.Background()); err != nil {
405			t.Fatalf("recycleUpstreamStorage: %v", err)
406		}
407		// The fake fails an apply over a claim that still exists; the sleeps are the wait.
408		e.requireOps("scale 0", "delete", "apply", "scale 1")
409		// One sleep for the pod that leaves, three for the claim that is terminating, one
410		// for the new pod. The code may poll the claim more often, never less.
411		if got := len(e.clk.sleeps); got < 5 {
412			t.Errorf("slept %d times (%v), want at least 5: the pod, the claim (3 reads) and the new pod", got, e.clk.sleeps)
413		}
414		for i, d := range e.clk.sleeps {
415			if d <= 0 || d > maxPollInterval {
416				t.Errorf("sleep #%d lasts %v, want a poll of at most %v", i+1, d, maxPollInterval)
417			}
418		}
419	}
