442		e.requireOps("scale 0", "delete", "apply")
443	
444		// The cluster is as the failure left it: the upstream cut, the claim gone.
445		e.k.applyReply = nil
446		e.kube.before = []upstreamRound{cutRound()}
447		e.kube.scaledAt = -1
448		e.k.ops = nil
449		if err := e.recycle(context.Background()); err != nil {
450			t.Fatalf("second recycleUpstreamStorage: %v", err)
451		}
452		// The upstream is already cut: no scale to 0; the claim is already gone: no delete.
453		e.requireOps("apply", "scale 1")
454		e.requireTouchesOnlyTheUpstream()
455	}
